require_once '../includes/config.php';require_once '../includes/db.php';require_once '../includes/customer_auth.php';startCustomerSession();ensureCustomerAuthSchema($conn);$c=loadSignedInCustomer($conn);if(!$c){header('Location: ../index.php?auth=login');exit;}$id=(int)($_GET['order_id']??0);$cid=(int)$c['id'];$s=$conn->prepare('SELECT product_id,quantity,description,notes FROM orders WHERE id=? AND customer_id=? LIMIT 1');$s->bind_param('ii',$id,$cid);$s->execute();$o=$s->get_result()->fetch_assoc();$s->close();if(!$o||!(int)$o['product_id']){header('Location: orders.php');exit;}$_SESSION['customer_reorder_prefill']=['source_order_id'=>$id,'description'=>$o['description']??'','notes'=>$o['notes']??''];$pid=(int)$o['product_id'];$qty=max(1,(int)$o['quantity']);?><!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover"><script>try{const key='brille_customer_cart_<?= (int)$c['id'] ?>';const cart=JSON.parse(localStorage.getItem(key)||'{}');cart['<?=$pid?>']=<?=$qty?>;localStorage.setItem(key,JSON.stringify(cart));}catch(e){}location.replace('cart.php?reorder=1');</script><p>Preparing your previous order… <a href="cart.php">Continue</a></p>
